"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_CELL = re.compile(r":?-+:?")


def _cell_text(value: object) -> str:
    """The escaped text of one cell."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _normalise_align(align: object, width: int) -> list[str | None]:
    """Validate *align* and return one alignment per column."""
    if align is None:
        return [None] * width
    if not isinstance(align, list) or len(align) != width:
        raise ValueError("align must be a list with one entry per column")
    result = []
    for value in align:
        if value not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {value!r}")
        result.append(value)
    return result


def _pad(text: str, width: int, align: str | None) -> str:
    """Pad *text* to *width* according to *align*."""
    space = width - len(text)
    if align == "right":
        return " " * space + text
    if align == "center":
        left = space // 2
        return " " * left + text + " " * (space - left)
    return text + " " * space


def _delimiter(width: int, align: str | None) -> str:
    """The delimiter cell for a column of *width*."""
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _format_line(
    cells: list[str], widths: list[int], alignments: list[str | None]
) -> str:
    padded = (_pad(cell, width, align) for cell, width, align in zip(cells, widths, alignments))
    return "| " + " | ".join(padded) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_cell_text(value) for value in header]
    alignments = _normalise_align(align, len(header_cells))

    body = []
    for row in rows:
        if len(row) > len(header_cells):
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (len(header_cells) - len(cells)))
        body.append(cells)

    widths = []
    for index, header_cell in enumerate(header_cells):
        width = max(3, len(header_cell))
        for cells in body:
            width = max(width, len(cells[index]))
        widths.append(width)

    lines = [_format_line(header_cells, widths, alignments)]
    lines.append(
        "| "
        + " | ".join(
            _delimiter(width, align) for width, align in zip(widths, alignments)
        )
        + " |"
    )
    for cells in body:
        lines.append(_format_line(cells, widths, alignments))
    return "\n".join(lines)


def _ends_with_escaped_pipe(line: str) -> bool:
    """Whether *line*, which ends in ``|``, ends in an escaped pipe."""
    backslashes = 0
    index = len(line) - 2
    while index >= 0 and line[index] == "\\":
        backslashes += 1
        index -= 1
    return backslashes % 2 == 1


def _split_cells(line: str) -> list[str]:
    """Split one table line into raw cells, dropping any border pipes."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not _ends_with_escaped_pipe(line):
        line = line[:-1]

    cells = []
    start = 0
    backslashes = 0
    for index, char in enumerate(line):
        if char == "|" and backslashes % 2 == 0:
            cells.append(line[start:index])
            start = index + 1
        if char == "\\":
            backslashes += 1
        else:
            backslashes = 0
    cells.append(line[start:])
    return cells


def _unescape(text: str) -> str:
    """Turn ``\\|`` back into ``|``."""
    return text.replace("\\|", "|")


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs at least two lines")

    header = [_unescape(cell.strip()) for cell in _split_cells(lines[0])]

    delimiter = [cell.strip() for cell in _split_cells(lines[1])]
    if len(delimiter) != len(header):
        raise ValueError("delimiter line does not match the header")

    alignments = []
    for cell in delimiter:
        if _DELIMITER_CELL.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left = cell.startswith(":")
        right = cell.endswith(":")
        if left and right:
            alignments.append("center")
        elif left:
            alignments.append("left")
        elif right:
            alignments.append("right")
        else:
            alignments.append(None)

    rows = []
    for line in lines[2:]:
        cells = [_unescape(cell.strip()) for cell in _split_cells(line)]
        if len(cells) != len(header):
            raise ValueError("row does not match the header")
        rows.append(cells)

    return header, rows, alignments

